insert into public.rubric_criteria (role, key, criterion_name, short_label, description, weight, score_anchors, position, rubric_version)
values
  ('pm', 'pm_ownership', 'End-to-End Product Ownership', 'Ownership', 'The CV shows the candidate personally owning a product area or feature from problem to live usage: they decided what to build, took it through release and tracked it afterwards. Strong looks like ''sole PM for X'', ''took N features from spec to release and tracked adoption'', or building something unasked (a prototype, a tool) that others then adopted. Supporting other PMs, writing specs for someone else''s roadmap, or ''part of a team that…'' is weaker.', 25, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Lists product responsibilities with no example of owning an outcome.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: Owned at least one feature or module end-to-end, with release and some follow-up.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Sole owner of a product area; repeatedly took work from problem to adoption and can show what happened after launch."}'::jsonb, 1, 'v1'),
  ('pm', 'pm_discovery', 'Customer & Problem Discovery', 'Discovery', 'The CV shows the candidate learning directly from the people who do the work: interviews, time embedded with operations teams, site visits, support-ticket analysis — and a product change that came from it. Ground-level operational exposure (e.g. running shipments, documentation, carrier coordination) counts when it shaped what was built. Generic ''user research'' or frameworks named without a finding is weak.', 20, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Mentions user research or customer focus without a specific finding.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: Describes a discovery activity and a product change that followed from it.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Repeated, first-hand time with users or operations teams, with specific findings that changed direction and a measured result."}'::jsonb, 2, 'v1'),
  ('pm', 'pm_shipping', 'Shipping & Outcome Orientation', 'Shipping', 'The CV shows things shipped in short cycles and judged by outcome, including stopping what didn''t work. Strong looks like counts of features shipped over a stated period, adoption or business metrics after launch, and evidence of killing or reversing features based on data and writing down why. Activity without outcomes (''managed the roadmap'', ''led sprints'') is weak.', 20, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Mentions launches with no outcomes.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: Shipped features with at least one measured post-launch outcome.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Consistent shipping cadence with measured outcomes, plus at least one feature killed or reworked on evidence."}'::jsonb, 3, 'v1'),
  ('pm', 'pm_ambiguity', 'Operating Without Structure', 'Ambiguity', 'The CV shows the candidate working where no playbook existed and creating one: first PM or first hire in a function, early-stage company, building the process/template/tool the team then adopted, fixing something nobody owned. Strong looks like ''built the first…'', ''no PM above me'', ''set up X that the team still uses''. Working inside a mature process run by others is weak.', 20, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Only structured environments; no sign of creating process or working without a lead.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: At least one instance of building a process, tool or function from nothing that others adopted.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Repeatedly first-in-seat or operating with no layer above, building the systems others then relied on."}'::jsonb, 4, 'v1'),
  ('pm', 'pm_technical', 'Technical & Systems Fluency', 'Technical', 'The CV shows the candidate working credibly with engineering on how the system works: APIs and integrations, data models, writing API documentation, SQL/analytics they did themselves, diagnosing incidents or data issues, or an engineering background applied to product decisions. A list of tools (JIRA, Figma) is not evidence.', 15, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Tool names only.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: One concrete example of technical work: an integration, API docs, data analysis or incident handled with engineering.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Deep, repeated technical contribution: built or specified integrations or data systems and made product calls on technical trade-offs."}'::jsonb, 5, 'v1'),
  ('spm', 'spm_platform', 'Platform / Integration Ownership', 'Platform', 'The CV shows the candidate owning a platform, integration or data layer — connections to carrier systems, ports, ERPs, partner APIs, or internal platform services other teams build on — and the outcome of that work (integration time cut, new customers unlocked, deals unblocked). Owning a consumer-facing feature set with no integration or platform component is weak.', 25, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Mentions integrations or platforms in passing.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: Owned at least one integration or platform capability with a stated result.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Owned an integration/platform roadmap across multiple systems with measured commercial or reliability impact."}'::jsonb, 1, 'v1'),
  ('spm', 'spm_decisions', 'Independent Product Decision-Making', 'Decisions', 'The CV shows the candidate making consequential product calls without a senior PM or committee above them and living with the results: build vs. buy vs. don''t-build, killing a product line, choosing an architecture direction, saying no to a customer. Strong looks like explicit decisions, the trade-off considered and what happened. ''Supported leadership decisions'' or ''presented options'' is weak.', 25, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Decision-making claimed without an example.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: At least one specific, consequential call made by the candidate with its outcome.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Repeated high-stakes calls owned without a layer above, including unpopular ones, with outcomes stated."}'::jsonb, 2, 'v1'),
  ('spm', 'spm_influence', 'Cross-Functional Influence & Alignment', 'Alignment', 'The CV shows the candidate getting sales, engineering, operations and leadership to agree on one plan and keep it: a roadmap others trusted, resolving conflicting priorities, turning field or sales input into agreed scope, leading post-mortems others acted on. Presenting to stakeholders without a result is weak.', 20, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Lists stakeholders worked with.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: One concrete case of aligning multiple functions on a decision or roadmap, with a result.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Sustained alignment across sales, engineering and operations with evidence the plan held and changed outcomes."}'::jsonb, 3, 'v1'),
  ('spm', 'spm_reliability', 'Reliability, Data & Systems Thinking', 'Reliability', 'The CV shows the candidate treating reliability and data quality as product work: incident ownership and post-mortems, data-quality standards, monitoring, reducing failures or lag, migrations done without data loss, SLAs customers depend on. Strong looks like measured reliability improvements the candidate drove.', 15, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Mentions quality or data without a specific example.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: Owned at least one reliability, data-quality or incident outcome with a result.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Set reliability or data standards and drove measured improvements across systems others depend on."}'::jsonb, 4, 'v1'),
  ('spm', 'spm_operating', 'Building Product Operating Systems', 'Operating system', 'The CV shows the candidate building how a product team works: prioritisation frameworks, PRD or review templates, sprint or planning rituals, onboarding for PMs, mentoring or hiring PMs — adopted by others. Following an existing process is weak.', 15, '{"0":"No evidence: the CV contains nothing relevant to this criterion.","1":"Minimal evidence: Mentions process or frameworks generally.","2":"Weak evidence: one specific example, but thin, indirect or without outcome.","3":"Moderate evidence: Created at least one practice, template or ritual that a team adopted.","4":"Strong evidence: several concrete examples, clearly the candidate''s own, with measurable results.","5":"Exceptional evidence: Built a product function''s operating model — rituals, standards, hiring or mentoring — that others adopted and that outlasted them."}'::jsonb, 5, 'v1')
